import os
from pathlib import Path

def count_files(path):
    p = Path(path)
    if not p.exists():
        return 0
    return sum(1 for f in p.rglob('*') if f.is_file())

print(f"gelen klasöründeki toplam dosya sayısı: {count_files('gelen')}")

