        # 2. YYYY-MM-DD (20xx-xx-xx)
        if ($file.Name -match '(20\d{2})(\d{2})(\d{2})') {
            $foundDate = @{ Year = $Matches[1]; Month = $Matches[2] }
        }
        elseif ($file.Name -match '(20\d{2})-(\d{2})-(\d{2})') {
            $foundDate = @{ Year = $Matches[1]; Month = $Matches[2] }
        }

        if ($foundDate) {
            $destFolder = Join-Path $archiveDir "$($foundDate.Year)\$($foundDate.Month)"
        } else {
            $destFolder = Join-Path $archiveDir "tarihsiz"
        }

        if (!(Test-Path $destFolder)) { New-Item -ItemType Directory -Path $destFolder -Force | Out-Null }

        $destFile = Join-Path $destFolder $file.Name

        # İsim çakışması kontrolü
        $count = 1
        while (Test-Path $destFile) {
            $baseName = $file.BaseName
            $destFile = Join-Path $destFolder "$($baseName)_$count$($file.Extension)"
            $count++
        }

        Move-Item -Path $file.FullName -Destination $destFile
        Write-Host "Taşındı: $($file.Name) -> $destFile"
    }
}

Write-Host "`nİşlem tamamlandı."

